  ?p brick:hasSubclass? ?class .
  ?p brick:isA? brick:Electric_Power .
} LIMIT 20

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?uri ?type WHERE {
  ?uri brick:isA ?type .
  FILTER(strstr(str(?type), "Electric"))
} LIMIT 100

